// LIN_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module LIN_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [15:0] c_cfg_bit,
  input logic  c_cfg_autobaud,
  input logic [5:0] c_hdr_id,
  input logic [5:0] c_pid_id,
  input logic [63:0] c_rsp_data,
  input logic [2:0] c_rsp_len,
  input logic  c_rsp_pub,
  input logic  c_rsp_enh,
  input logic [63:0] c_rx_data,
  input logic [5:0] c_rx_id,
  input logic [2:0] c_rx_len,
  input logic [15:0] c_bit_time,
  input logic  c_hdr_valid,
  input logic  c_hdr_ready,
  input logic  c_pid_valid,
  input logic  c_rsp_valid,
  input logic  c_rsp_ready,
  input logic  c_rx_valid,
  input logic  c_tx_done,
  input logic  c_err_bit,
  input logic  c_err_sync,
  input logic  c_err_parity,
  input logic  c_err_frame,
  input logic  c_err_chk,
  input logic  c_err_timeout
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 15;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:14];          // model of every stored word
  logic [14:0] m_set;                // interrupt bits set this clock
  logic m_state_HDR;          // full / valid pulse / available
  logic m_state_PID;          // full / valid pulse / available
  logic m_state_RSP;          // full / valid pulse / available
  logic m_state_RX;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_tx_done) m_set[0] = 1'b1;
    if (c_err_bit) m_set[1] = 1'b1;
    if (c_err_sync) m_set[2] = 1'b1;
    if (c_err_parity) m_set[3] = 1'b1;
    if (c_err_frame) m_set[4] = 1'b1;
    if (c_err_chk) m_set[5] = 1'b1;
    if (c_err_timeout) m_set[6] = 1'b1;
    if (m_state_HDR && c_hdr_ready) m_set[7] = 1'b1;
    if (m_wr && m_map && (m_idx == 6) && m_state_HDR) m_set[8] = 1'b1;
    if (c_pid_valid && !m_state_PID) m_set[9] = 1'b1;
    if (c_pid_valid && m_state_PID && (m_rd && m_map && m_idx == 7)) m_set[9] = 1'b1;
    if (c_pid_valid && m_state_PID && !(m_rd && m_map && m_idx == 7)) m_set[10] = 1'b1;
    if (m_state_RSP && c_rsp_ready) m_set[11] = 1'b1;
    if (m_wr && m_map && (m_idx == 8 || m_idx == 9 || m_idx == 10) && m_state_RSP) m_set[12] = 1'b1;
    if (c_rx_valid && !m_state_RX) m_set[13] = 1'b1;
    if (c_rx_valid && m_state_RX && (m_rd && m_map && m_idx == 13)) m_set[13] = 1'b1;
    if (c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 13)) m_set[14] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'hA2C;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_state_HDR <= 0;
      m_state_PID <= 0;
      m_state_RSP <= 0;
      m_state_RX <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7FFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFF;
      if (m_wr && m_map && m_idx == 6 && !m_state_HDR) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h3F;
      if (m_wr && m_map && m_idx == 6 && !m_state_HDR) m_state_HDR <= 1;
      if (m_state_HDR && c_hdr_ready) m_state_HDR <= 0;
      if (c_pid_valid && (!m_state_PID || (m_rd && m_map && m_idx == 7))) begin
        m_w[7] <= (32'(c_pid_id[5:0]) << 0);
        m_state_PID <= 1;
      end else if ((m_rd && m_map && m_idx == 7)) m_state_PID <= 0;
      if (m_wr && m_map && m_idx == 8 && !m_state_RSP) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9 && !m_state_RSP) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10 && !m_state_RSP) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 10 && !m_state_RSP) m_state_RSP <= 1;
      if (m_state_RSP && c_rsp_ready) m_state_RSP <= 0;
      if (c_rx_valid && (!m_state_RX || (m_rd && m_map && m_idx == 13))) begin
        m_w[11] <= (32'(c_rx_data[31:0]) << 0);
        m_w[12] <= (32'(c_rx_data[63:32]) << 0);
        m_w[13] <= (32'(c_rx_id[5:0]) << 0) | (32'(c_rx_len[2:0]) << 6);
        m_state_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 13)) m_state_RX <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h4C490200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RX, m_state_RSP, m_state_PID, m_state_HDR});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return (32'(c_bit_time) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][14:0] & m_w[2][14:0]))
  `SVA_INV(a_core_cfg_bit, c_cfg_bit == m_w[5][15:0])
  `SVA_INV(a_core_cfg_autobaud, c_cfg_autobaud == m_w[5][16:16])
  `SVA_INV(a_core_hdr_id, c_hdr_id == m_w[6][5:0])
  `SVA_INV(a_core_rsp_data_31_0, c_rsp_data[31:0] == m_w[8][31:0])
  `SVA_INV(a_core_rsp_data_63_32, c_rsp_data[63:32] == m_w[9][31:0])
  `SVA_INV(a_core_rsp_len, c_rsp_len == m_w[10][2:0])
  `SVA_INV(a_core_rsp_pub, c_rsp_pub == m_w[10][3:3])
  `SVA_INV(a_core_rsp_enh, c_rsp_enh == m_w[10][4:4])
  `SVA_INV(a_core_hdr_valid, c_hdr_valid == m_state_HDR)
  `SVA_INV(a_core_rsp_valid, c_rsp_valid == m_state_RSP)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_bit == 16'hA2C && c_cfg_autobaud == 1'h0 && c_hdr_id == 6'h0 && c_rsp_data[31:0] == 32'h0 && c_rsp_data[63:32] == 32'h0 && c_rsp_len == 3'h0 && c_rsp_pub == 1'h0 && c_rsp_enh == 1'h0 && !c_hdr_valid && !c_rsp_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG, m_wr && m_map && m_idx == 5)
  `FC(rd_HDR, m_rd && m_map && m_idx == 6)
  `FC(wr_HDR, m_wr && m_map && m_idx == 6)
  `FC(rd_PID, m_rd && m_map && m_idx == 7)
  `FC(wr_PID, m_wr && m_map && m_idx == 7)
  `FC(rd_RSP0, m_rd && m_map && m_idx == 8)
  `FC(wr_RSP0, m_wr && m_map && m_idx == 8)
  `FC(rd_RSP1, m_rd && m_map && m_idx == 9)
  `FC(wr_RSP1, m_wr && m_map && m_idx == 9)
  `FC(rd_RSP2, m_rd && m_map && m_idx == 10)
  `FC(wr_RSP2, m_wr && m_map && m_idx == 10)
  `FC(rd_RX0, m_rd && m_map && m_idx == 11)
  `FC(wr_RX0, m_wr && m_map && m_idx == 11)
  `FC(rd_RX1, m_rd && m_map && m_idx == 12)
  `FC(wr_RX1, m_wr && m_map && m_idx == 12)
  `FC(rd_RX2, m_rd && m_map && m_idx == 13)
  `FC(wr_RX2, m_wr && m_map && m_idx == 13)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 14)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 14)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_SENT_set, m_set[0])
  `FC(irq_SENT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_SENT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_SENT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERR_BIT_set, m_set[1])
  `FC(irq_ERR_BIT_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERR_BIT_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERR_BIT_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ERR_SYNC_set, m_set[2])
  `FC(irq_ERR_SYNC_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ERR_SYNC_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ERR_SYNC_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_PARITY_set, m_set[3])
  `FC(irq_ERR_PARITY_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_PARITY_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_PARITY_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ERR_FRAME_set, m_set[4])
  `FC(irq_ERR_FRAME_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ERR_FRAME_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ERR_FRAME_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_ERR_CHK_set, m_set[5])
  `FC(irq_ERR_CHK_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_ERR_CHK_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_ERR_CHK_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_ERR_TIMEOUT_set, m_set[6])
  `FC(irq_ERR_TIMEOUT_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_ERR_TIMEOUT_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_ERR_TIMEOUT_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_HDR_DONE_set, m_set[7])
  `FC(irq_HDR_DONE_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_HDR_DONE_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_HDR_DONE_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_HDR_OVF_set, m_set[8])
  `FC(irq_HDR_OVF_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_HDR_OVF_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_HDR_OVF_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(irq_PID_AVAIL_set, m_set[9])
  `FC(irq_PID_AVAIL_cleared, m_w[1][9] && m_wr && m_map && m_idx == 1 && PWDATA[9] && PSTRB[1])
  `FC(irq_PID_AVAIL_masked, m_w[1][9] && !m_w[2][9])
  `FC(irq_PID_AVAIL_drives_pin, m_w[1][9] && m_w[2][9] && irq)
  `FC(irq_PID_OVF_set, m_set[10])
  `FC(irq_PID_OVF_cleared, m_w[1][10] && m_wr && m_map && m_idx == 1 && PWDATA[10] && PSTRB[1])
  `FC(irq_PID_OVF_masked, m_w[1][10] && !m_w[2][10])
  `FC(irq_PID_OVF_drives_pin, m_w[1][10] && m_w[2][10] && irq)
  `FC(irq_RSP_DONE_set, m_set[11])
  `FC(irq_RSP_DONE_cleared, m_w[1][11] && m_wr && m_map && m_idx == 1 && PWDATA[11] && PSTRB[1])
  `FC(irq_RSP_DONE_masked, m_w[1][11] && !m_w[2][11])
  `FC(irq_RSP_DONE_drives_pin, m_w[1][11] && m_w[2][11] && irq)
  `FC(irq_RSP_OVF_set, m_set[12])
  `FC(irq_RSP_OVF_cleared, m_w[1][12] && m_wr && m_map && m_idx == 1 && PWDATA[12] && PSTRB[1])
  `FC(irq_RSP_OVF_masked, m_w[1][12] && !m_w[2][12])
  `FC(irq_RSP_OVF_drives_pin, m_w[1][12] && m_w[2][12] && irq)
  `FC(irq_RX_AVAIL_set, m_set[13])
  `FC(irq_RX_AVAIL_cleared, m_w[1][13] && m_wr && m_map && m_idx == 1 && PWDATA[13] && PSTRB[1])
  `FC(irq_RX_AVAIL_masked, m_w[1][13] && !m_w[2][13])
  `FC(irq_RX_AVAIL_drives_pin, m_w[1][13] && m_w[2][13] && irq)
  `FC(irq_RX_OVF_set, m_set[14])
  `FC(irq_RX_OVF_cleared, m_w[1][14] && m_wr && m_map && m_idx == 1 && PWDATA[14] && PSTRB[1])
  `FC(irq_RX_OVF_masked, m_w[1][14] && !m_w[2][14])
  `FC(irq_RX_OVF_drives_pin, m_w[1][14] && m_w[2][14] && irq)
  `FC(HDR_handshake, m_state_HDR && c_hdr_ready)
  `FC(HDR_backpressure, m_state_HDR && !c_hdr_ready)
  `FC(HDR_write_while_full, m_wr && m_map && m_idx == 6 && m_state_HDR)
  `FC(PID_capture, c_pid_valid && !m_state_PID)
  `FC(PID_overflow, c_pid_valid && m_state_PID && !(m_rd && m_map && m_idx == 7))
  `FC(PID_pop, m_rd && m_map && m_idx == 7 && m_state_PID)
  `FC(PID_read_empty, m_rd && m_map && m_idx == 7 && !m_state_PID)
  `FC(PID_pop_and_capture, c_pid_valid && m_state_PID && m_rd && m_map && m_idx == 7)
  `FC(RSP_handshake, m_state_RSP && c_rsp_ready)
  `FC(RSP_backpressure, m_state_RSP && !c_rsp_ready)
  `FC(RSP_write_while_full, m_wr && m_map && m_idx == 10 && m_state_RSP)
  `FC(RX_capture, c_rx_valid && !m_state_RX)
  `FC(RX_overflow, c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 13))
  `FC(RX_pop, m_rd && m_map && m_idx == 13 && m_state_RX)
  `FC(RX_read_empty, m_rd && m_map && m_idx == 13 && !m_state_RX)
  `FC(RX_pop_and_capture, c_rx_valid && m_state_RX && m_rd && m_map && m_idx == 13)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind LIN_apb LIN_apb_sva u_apb_sva (.*);
